/* Exercise the runtime emitted by seed-min, not a duplicate implementation.
 * Run after the seed-only borrow fixture has been generated by test-seed-borrow.
 */
#define main sx_fixture_main
#include "seed_tests/borrow.c"
#undef main
#include <assert.h>
int main(void){
  char *live[4096];
  assert(!sx_sb_is("foreign literal"));
  sx_sb_free("foreign literal");
  for(int i=0;i<4096;i++) live[i]=sx_sb_from("abcdef");
  assert(sx_sb_count==4096);
  for(int i=0;i<4096;i++){
    assert(sx_sb_is(live[i]));
    assert(!sx_sb_is(live[i]+1));
    sx_sb_free(live[i]+1); /* Interior pointers are borrowed, not owning. */
    assert(!strcmp(live[i],"abcdef"));
  }
  char *overlap=sx_cat(live[0],live[0]+2);
  assert(!strcmp(overlap,"abcdefcdef"));
  assert(!strcmp(live[0],"abcdef"));
  sx_sb_free(overlap);
  for(int i=0;i<4096;i+=2){ sx_sb_free(live[i]); live[i]=NULL; }
  assert(sx_sb_count==2048);
  for(int i=0;i<4096;i+=2) live[i]=sx_sb_from("replacement");
  assert(sx_sb_count==4096);
  for(int i=0;i<4096;i++){
    assert(sx_sb_is(live[i]));
    assert(!strcmp(live[i],i%2?"abcdef":"replacement"));
    sx_sb_free(live[i]);
  }
  assert(sx_sb_count==0);
  assert(!sx_sb_is(NULL));
  sx_sb_free(NULL);
  puts("registry-ok");
  return 0;
}
